describe("BaseApi scheme credentials", () => {
  const bearer = new TestAuthenticator({ Authorization: "Bearer b" });
  const apiKey = new TestAuthenticator({ "X-Api-Key": "k" });

  test("bhv authintegration 014 resolves the credential of the first listed scheme the client holds", () => {
    const testApi = new TestableApi(undefined, undefined, null, {
      bearer,
      apiKey,
    });

    expect(testApi.resolve(["basic", "apiKey", "bearer"])).toBe(apiKey);
    expect(testApi.resolve(["bearer", "apiKey"])).toBe(bearer);
  });

  test("bhv auth 021 resolves nothing when the client holds none of the listed schemes", () => {
    const testApi = new TestableApi(undefined, undefined, null, { bearer });

    expect(testApi.resolve(["basic", "apiKey"])).toBeUndefined();
    expect(testApi.resolve([])).toBeUndefined();
  });

  test("bhv authintegration 016 resolves nothing for a client built with no scheme credentials", () => {
    expect(new TestableApi().resolve(["bearer"])).toBeUndefined();
  });

  test.each(["constructor", "toString", "__proto__", "hasOwnProperty"])(
    "a scheme named %s never resolves to a member of Object.prototype",
    (name) => {
      expect(
        new TestableApi(undefined, undefined, null, { bearer }).resolve([name]),
      ).toBeUndefined();
    },
  );

  test("bhv authintegration 003 a resolved scheme credential is the one the request carries, not the client-level authenticator", async () => {
    const client = new CapturingApiClient();
    const testApi = new TestableApi(
      client,
      new Configuration({ baseUrl: "http://localhost" }),
      new TestAuthenticator({ Authorization: "Bearer client-level" }),
      { bearer },
    );

    await testApi.call(
      "GET",
      "/test/echo",
      {},
      {},
      null,
      ["application/json"],
      "application/json",
      null,
      testApi.resolve(["bearer"]),
    );

    expect(client.capturedHeaders["Authorization"]).toBe("Bearer b");
  });

  test("bhv authintegration 007 each operation sends the credential of its own scheme", async () => {
    const client = new CapturingApiClient();
    const testApi = new TestableApi(
      client,
      new Configuration({ baseUrl: "http://localhost" }),
      null,
      { bearer, apiKey },
    );

    await testApi.call(
      "GET",
      "/test/echo",
      {},
      {},
      null,
      ["application/json"],
      "application/json",
      null,
      testApi.resolve(["bearer"]),
    );
    expect(client.capturedHeaders["Authorization"]).toBe("Bearer b");
    expect(client.capturedHeaders["X-Api-Key"]).toBeUndefined();

    await testApi.call(
      "GET",
      "/test/echo",
      {},
      {},
      null,
      ["application/json"],
      "application/json",
      null,
      testApi.resolve(["apiKey"]),
    );
    expect(client.capturedHeaders["X-Api-Key"]).toBe("k");
    expect(client.capturedHeaders["Authorization"]).toBeUndefined();
  });

  test("bhv authintegration 008 a call with no scheme credential falls back to the client-level authenticator", async () => {
    const client = new CapturingApiClient();
    const clientAuth = new TestAuthenticator({
      "X-Client-Auth": "client-level-token",
    });
    const testApi = new TestableApi(
      client,
      new Configuration({ baseUrl: "http://localhost" }),
      clientAuth,
      { bearer },
    );

    await testApi.call(
      "GET",
      "/test/echo",
      {},
      {},
      null,
      ["application/json"],
      "application/json",
      null,
      testApi.resolve(["apiKey"]),
    );

    expect(client.capturedHeaders["X-Client-Auth"]).toBe("client-level-token");
  });

  test("bhv authintegration 009 falls back to client-level authenticator when no scheme credential resolved", async () => {
    const client = new CapturingApiClient();
    const config = new Configuration({ baseUrl: "http://localhost" });
    const clientAuth = new TestAuthenticator({
      "X-Client-Auth": "client-level-token",
    });
    const testApi = new TestableApi(client, config, clientAuth);
    await testApi.call(
      "GET",
      "/test/echo",
      {},
      {},
      null,
      ["application/json"],
      "application/json",
      null,
      null,
    );
    expect(client.capturedHeaders["X-Client-Auth"]).toBe("client-level-token");
  });

  test("bhv authintegration 013 a resolved authenticator replaces the client-level authenticator", async () => {
    const client = new CapturingApiClient();
    const config = new Configuration({ baseUrl: "http://localhost" });
    const clientAuth = new TestAuthenticator({
      "X-Client-Auth": "client-level-token",
    });
    const perCallAuth = new TestAuthenticator({
      "X-Client-Auth": "per-call-token",
    });
    const testApi = new TestableApi(client, config, clientAuth);
    await testApi.call(
      "GET",
      "/test/echo",
      {},
      {},
      null,
      ["application/json"],
      "application/json",
      null,
      perCallAuth,
    );
    expect(client.capturedHeaders["X-Client-Auth"]).toBe("per-call-token");
  });
});

describe("SecurityNoneSuppressesClientAuth", () => {
  /*
   * SECURITY-NONE (Wave A2): an operation declared `security: []` in the
   * spec is explicitly unauthenticated. Even when the client is configured
   * WITH an authenticator, that operation must carry NO credential on the
   * wire — no Authorization header, no api-key header/query-param, no auth
   * cookie. The api method passes the internal NO_AUTH sentinel for such
   * operations, and base_api resolves the sentinel to "apply no auth"
   * rather than falling back to the client authenticator.
   *
   * `getInventory` is declared `security: []`, so it is the canonical
   * unauthenticated operation. The CapturingApiClient records exactly what
   * BaseApi hands to the transport, so we assert against the real outgoing
   * request of the real operation.
   */
  test("bhv authintegration 005 security:[] op suppresses a configured Bearer authenticator", async () => {
    const client = new CapturingApiClient();
    client.responseBody = "{}";
    const config = new Configuration({ baseUrl: "http://localhost" });
    const clientAuth = new BearerAuthenticator(
      "http://localhost",
      "secret-token-123",
    );
    const storeApi = new StoreApi(client, config, clientAuth);
    try {
      await storeApi.getInventory();
    } catch {
      // capture-only: we only care about the outbound request
    }
    // No Authorization header reached the wire despite the configured Bearer.
    expect(client.capturedHeaders["Authorization"]).toBeUndefined();
    const headerKeys = Object.keys(client.capturedHeaders).map((k) =>
      k.toLowerCase(),
    );
    expect(headerKeys).not.toContain("authorization");
    // And no secret leaked into the value of any header.
    for (const value of Object.values(client.capturedHeaders)) {
      expect(value).not.toContain("secret-token-123");
    }
  });

  test("bhv authintegration 015 security:[] op suppresses a configured api-key (header, query, cookie)", async () => {
    // Header-located api key.
    const headerClient = new CapturingApiClient();
    headerClient.responseBody = "{}";
    const headerAuth = new ApiKeyAuthenticator(
      "http://localhost",
      "X-API-Key",
      "key-secret-xyz",
      ApiKeyLocation.HEADER,
    );
    const headerApi = new StoreApi(
      headerClient,
      new Configuration({ baseUrl: "http://localhost" }),
      headerAuth,
    );
    try {
      await headerApi.getInventory();
    } catch {
      // capture-only
    }
    expect(headerClient.capturedHeaders["X-API-Key"]).toBeUndefined();
    expect(headerClient.capturedHeaders["Cookie"]).toBeUndefined();
    for (const value of Object.values(headerClient.capturedHeaders)) {
      expect(value).not.toContain("key-secret-xyz");
    }

    // Query-located api key — must not appear in the URL.
    const queryClient = new CapturingApiClient();
    queryClient.responseBody = "{}";
    const queryAuth = new ApiKeyAuthenticator(
      "http://localhost",
      "api_key",
      "key-secret-xyz",
      ApiKeyLocation.QUERY,
    );
    const queryApi = new StoreApi(
      queryClient,
      new Configuration({ baseUrl: "http://localhost" }),
      queryAuth,
    );
    try {
      await queryApi.getInventory();
    } catch {
      // capture-only
    }
    expect(queryClient.capturedUrl).not.toContain("api_key=");
    expect(queryClient.capturedUrl).not.toContain("key-secret-xyz");

    // Cookie-located api key — must not appear in the Cookie header.
    const cookieClient = new CapturingApiClient();
    cookieClient.responseBody = "{}";
    const cookieAuth = new ApiKeyAuthenticator(
      "http://localhost",
      "SESSION_ID",
      "key-secret-xyz",
      ApiKeyLocation.COOKIE,
    );
    const cookieApi = new StoreApi(
      cookieClient,
      new Configuration({ baseUrl: "http://localhost" }),
      cookieAuth,
    );
    try {
      await cookieApi.getInventory();
    } catch {
      // capture-only
    }
    expect(cookieClient.capturedHeaders["Cookie"]).toBeUndefined();
    for (const value of Object.values(cookieClient.capturedHeaders)) {
      expect(value).not.toContain("key-secret-xyz");
    }
  });

  /*
   * SECURED (over-suppression guard): a SECURED operation with a configured
   * client authenticator and NO per-call override must STILL apply the
   * credential. This is the Wave A1 regression guard — the sentinel fix
   * must suppress auth ONLY for security:[] operations, never for secured
   * ones. `addPet` is a secured operation.
   */
  test("secured op still sends the configured authenticator credential", async () => {
    const client = new CapturingApiClient();
    client.responseBody = '{"id":1,"name":"Fido"}';
    const config = new Configuration({ baseUrl: "http://localhost" });
    const clientAuth = new BearerAuthenticator(
      "http://localhost",
      "secret-token-123",
    );
    const petApi = new PetApi(client, config, clientAuth);
    try {
      await petApi.addPet({ name: "Fido", photoUrls: new Set<string>() });
    } catch {
      // capture-only
    }
    expect(client.capturedHeaders["Authorization"]).toBe(
      "Bearer secret-token-123",
    );
  });

  /*
   * A request body keeps its required fields at compile time: the
   * `@ts-expect-error` below fails the type check if DeepInput ever makes
   * every property optional again.
   */
  test("a request body missing a required field is a compile error", async () => {
    const petApi = new PetApi(
      new CapturingApiClient(),
      new Configuration({ baseUrl: "http://localhost" }),
    );
    // @ts-expect-error photoUrls is required
    const missing = petApi.addPet({ name: "Fido" });
    await missing.catch(() => undefined);
    expect(missing).toBeInstanceOf(Promise);
  });

  /*
   * INHERITED GLOBAL SECURITY: `getPetById` declares no security of its own, so
   * it inherits the global requirement. This generator strips the inherited auth
   * methods off such an operation, so the api method passes null (not the
   * NO_AUTH sentinel) and base_api falls back to the client-level authenticator.
   * A configured client credential MUST reach the wire — the regression that
   * silently dropped auth on every inherited-security operation.
   */
  test("bhv authintegration 012 inherited-security op applies the configured authenticator credential", async () => {
    const client = new CapturingApiClient();
    client.responseBody = '{"id":1,"name":"Fido","photoUrls":[]}';
    const config = new Configuration({ baseUrl: "http://localhost" });
    const clientAuth = new BearerAuthenticator(
      "http://localhost",
      "secret-token-123",
    );
    const petApi = new PetApi(client, config, clientAuth);
    try {
      await petApi.getPetById(1);
    } catch {
      // capture-only
    }
    expect(client.capturedHeaders["Authorization"]).toBe(
      "Bearer secret-token-123",
    );
  });
});

describe("Container response leaves are type-checked", () => {
  test("getInventory rejects a quoted number in the integer map", async () => {
    const client = new CapturingApiClient();
    client.responseBody = '{"available":"5"}';
    const storeApi = new StoreApi(
      client,
      new Configuration({ baseUrl: "http://localhost" }),
    );
    await expect(storeApi.getInventory()).rejects.toThrow(
      "Expected int32 but received: string",
    );
  });

  test("getInventory rejects a fractional number in the integer map", async () => {
    const client = new CapturingApiClient();
    client.responseBody = '{"available":7.5}';
    const storeApi = new StoreApi(
      client,
      new Configuration({ baseUrl: "http://localhost" }),
    );
    await expect(storeApi.getInventory()).rejects.toThrow(
      "Expected int32 but received: number",
    );
  });

  test("getInventory rejects an out-of-range number in the integer map", async () => {
    const client = new CapturingApiClient();
    client.responseBody = '{"available":3000000000}';
    const storeApi = new StoreApi(
      client,
      new Configuration({ baseUrl: "http://localhost" }),
    );
    await expect(storeApi.getInventory()).rejects.toThrow(SerializationError);
  });

  test("getInventory still decodes integer values", async () => {
    const client = new CapturingApiClient();
    client.responseBody = '{"available":5,"sold":2}';
    const storeApi = new StoreApi(
      client,
      new Configuration({ baseUrl: "http://localhost" }),
    );
    await expect(storeApi.getInventory()).resolves.toEqual({
      available: 5,
      sold: 2,
    });
  });
});

describe("TypedErrorBodyTests", () => {
  test("bhv errors 029 getTypedErrorBody deserializes the raw body into the requested class", () => {
    const err = new BadRequestError("boom", {}, '{"id":42,"name":"Dogs"}');
    const typed = err.getTypedErrorBody(Category);
    expect(typed).not.toBeNull();
    expect(typed).toBeInstanceOf(Category);
    expect(typed!.id).toBe(42);
    expect(typed!.name).toBe("Dogs");
  });

  test("bhv errors 030 getTypedErrorBody returns null when there is no response body", () => {
    const err = new BadRequestError("boom", {}, null);
    expect(err.getTypedErrorBody(Category)).toBeNull();
  });

  test("bhv errors 028 getTypedErrorBody returns null for an empty-string response body", () => {
    const err = new BadRequestError("boom", {}, "");
    expect(err.getTypedErrorBody(Category)).toBeNull();
  });
});

describe("request cancellation against the slow endpoint", () => {
  const slow = (
    testApi: TestableApi,
    requestOptions?: RequestOptions,
  ): Promise<unknown> =>
    testApi
      .callForResult(
        "GET",
        `${chasmUrl}/test/slow`,
        {},
        {},
        null,
        ["application/json"],
        "application/json",
        null,
        undefined,
        requestOptions,
      )
      .catch((e: unknown) => e);

  test("a per-call signal aborts the in-flight request with an AbortError", async () => {
    const controller = new AbortController();
    const testApi = new TestableApi(
      new DefaultApiClient(),
      Configuration.defaultConfiguration(),
    );
    const pending = slow(testApi, { signal: controller.signal });
    setTimeout(() => controller.abort(), 100);
    const error = await pending;
    expect((error as Error).name).toBe("AbortError");
    expect(error).not.toBeInstanceOf(NetworkTimeoutError);
  }, 15000);

  test("an already aborted per-call signal rejects without waiting", async () => {
    const testApi = new TestableApi(
      new DefaultApiClient(),
      Configuration.defaultConfiguration(),
    );
    const error = await slow(testApi, { signal: AbortSignal.abort() });
    expect((error as Error).name).toBe("AbortError");
  });

  test("a client-level signal aborts the in-flight request with an AbortError", async () => {
    const controller = new AbortController();
    const config = Configuration.builder().signal(controller.signal).build();
    const testApi = new TestableApi(new DefaultApiClient(), config);
    const pending = slow(testApi);
    setTimeout(() => controller.abort(), 100);
    const error = await pending;
    expect((error as Error).name).toBe("AbortError");
    expect(error).not.toBeInstanceOf(NetworkTimeoutError);
  }, 15000);

  test("either the client-level or the per-call signal cancels the merged request", async () => {
    const clientController = new AbortController();
    const callController = new AbortController();
    const config = Configuration.builder()
      .signal(clientController.signal)
      .build();
    const testApi = new TestableApi(new DefaultApiClient(), config);
    const pending = slow(testApi, { signal: callController.signal });
    setTimeout(() => callController.abort(), 100);
    const error = await pending;
    expect((error as Error).name).toBe("AbortError");
    expect(clientController.signal.aborted).toBe(false);
  }, 15000);

  test("the timeout still raises NetworkTimeoutError when no signal fires", async () => {
    const transport = TransportOptions.builder().timeout(300).build();
    const testApi = new TestableApi(
      new DefaultApiClient(transport),
      Configuration.defaultConfiguration(),
    );
    const error = await slow(testApi, { signal: new AbortController().signal });
    expect(error).toBeInstanceOf(NetworkTimeoutError);
  }, 15000);
});

class RecordingApiClient implements ApiClient {
  statusCode = 200;
  method = "";
  url = "";
  headers: Record<string, string> = {};
  sendOptions: SendRequestOptions | undefined;
  async sendRequest(
    method: string,
    url: string,
    headers: Record<string, string>,
    _body: string | Buffer | Record<string, unknown> | null,
    options?: SendRequestOptions,
  ): Promise<ApiHttpResponse> {
    this.method = method;
    this.url = url;
    this.headers = { ...headers };
    this.sendOptions = options;
    return {
      statusCode: this.statusCode,
      body: "{}",
      headers: { "content-type": "application/json" },
    };
  }
}

describe("BaseApi error request context", () => {
  const fail = async (
    client: RecordingApiClient,
    method: string,
    path: string,
    baseUrl = "http://localhost",
  ): Promise<ApiError> => {
    const testApi = new TestableApi(client, new Configuration({ baseUrl }));
    try {
      await testApi.callForResult(
        method,
        path,
        { page: "2" },
        {},
        null,
        ["application/json"],
        "application/json",
        null,
      );
    } catch (e) {
      return e as ApiError;
    }
    throw new Error("expected the call to fail");
  };

  test("bhv errors 036 the error carries the method and the path without the query string", async () => {
    const client = new RecordingApiClient();
    client.statusCode = 404;
    const err = await fail(client, "GET", "/items/7");
    expect(err).toBeInstanceOf(NotFoundError);
    expect(err.requestMethod).toBe("GET");
    expect(err.requestPath).toBe("/items/7");
    expect(client.url).toBe("http://localhost/items/7?page=2");
  });

  test("bhv errors 027 the path keeps the base path of the server and drops the host", async () => {
    const client = new RecordingApiClient();
    client.statusCode = 500;
    const err = await fail(
      client,
      "POST",
      "/items",
      "https://api.example.com/v3",
    );
    expect(err.requestMethod).toBe("POST");
    expect(err.requestPath).toBe("/v3/items");
  });

  test("bhv errors 026 the rendered request line never carries the query string", async () => {
    const client = new RecordingApiClient();
    client.statusCode = 404;
    const err = await fail(client, "GET", "/items/7");
    expect(err.requestPath).not.toContain("?");
    expect(err.toString()).toContain("\nRequest: GET /items/7\n");
    expect(err.toString()).not.toContain("page=2");
  });

  test("bhv errors 048 418 throws ClientError", async () => {
    const client = new RecordingApiClient();
    client.statusCode = 418;
    const err = await fail(client, "GET", "/items/7");
    expect(err).toBeInstanceOf(ClientError);
  });

  test("a relative base URL gives the path without the query string", async () => {
    const client = new RecordingApiClient();
    client.statusCode = 418;
    const err = await fail(client, "PUT", "/items/7", "/api/v3");
    expect(err.requestPath).toBe("/api/v3/items/7");
  });

  test("the rendered message names the request", async () => {
    const client = new RecordingApiClient();
    client.statusCode = 503;
    const err = await fail(client, "DELETE", "/items/7");
    expect(err.toString()).toBe(
      'API returned status code 503\nHTTP status code: 503\nRequest: DELETE /items/7\nResponse headers: {"content-type":"application/json"}\nResponse body: {}',
    );
  });
});

describe("BaseApi per-call request options", () => {
  const send = async (
    client: RecordingApiClient,
    requestOptions?: RequestOptions,
    config?: Configuration,
    headerParams: Record<string, string> = {},
  ): Promise<void> => {
    const testApi = new TestableApi(
      client,
      config ?? new Configuration({ baseUrl: "http://localhost" }),
    );
    await testApi.callForResult(
      "GET",
      "/items",
      {},
      headerParams,
      null,
      ["application/json"],
      "application/json",
      null,
      undefined,
      requestOptions,
    );
  };

  test("without per-call options the transport defaults apply", async () => {
    const client = new RecordingApiClient();
    await send(client);
    expect(client.sendOptions?.timeout).toBeUndefined();
    expect(client.sendOptions?.maxRetries).toBeUndefined();
  });

  test("bhv retries 009 timeout and maxRetries reach the transport", async () => {
    const client = new RecordingApiClient();
    await send(client, { timeout: 250, maxRetries: 0 });
    expect(client.sendOptions?.timeout).toBe(250);
    expect(client.sendOptions?.maxRetries).toBe(0);
  });

  test("bhv options 053 per-call options take effect on that one call only", async () => {
    const client = new RecordingApiClient();
    await send(client, { timeout: 250, maxRetries: 0 });
    expect(client.sendOptions?.timeout).toBe(250);
    await send(client);
    expect(client.sendOptions?.timeout).toBeUndefined();
    expect(client.sendOptions?.maxRetries).toBeUndefined();
  });

  test("bhv options 055 a call without per-call options leaves the client default headers in force", async () => {
    const client = new RecordingApiClient();
    const config = new Configuration({
      baseUrl: "http://localhost",
      defaultHeaders: { "X-Region": "default" },
    });
    await send(client, undefined, config);
    expect(client.headers["X-Region"]).toBe("default");
    expect(client.sendOptions?.timeout).toBeUndefined();
  });

  test("bhv options 056 a per-call timeout of zero or less, or a negative retry count, is refused before any request is sent", async () => {
    const client = new RecordingApiClient();
    await expect(send(client, { timeout: 0 })).rejects.toThrow(
      /Invalid timeout/,
    );
    await expect(send(client, { maxRetries: -1 })).rejects.toThrow(
      /Invalid maxRetries/,
    );
    expect(client.url).toBe("");
  });

  test("bhv options 057 a per-call timeout below one millisecond is refused", async () => {
    await expect(
      send(new RecordingApiClient(), { timeout: 0.5 }),
    ).rejects.toThrow(/Invalid timeout/);
  });

  test("bhv transport 002 a null timeout reaches the transport as no timeout", async () => {
    const client = new RecordingApiClient();
    await send(client, { timeout: null });
    expect(client.sendOptions?.timeout).toBeNull();
  });

  test.each([[0], [-1], [Number.NaN]])(
    "a timeout of %s is refused",
    async (timeout) => {
      await expect(send(new RecordingApiClient(), { timeout })).rejects.toThrow(
        /Invalid timeout/,
      );
    },
  );

  test.each([[-1], [1.5], [Number.NaN]])(
    "maxRetries of %s is refused",
    async (maxRetries) => {
      await expect(
        send(new RecordingApiClient(), { maxRetries }),
      ).rejects.toThrow(/Invalid maxRetries/);
    },
  );

  test("bhv authintegration 011 the call is not sent when an option is refused", async () => {
    const client = new RecordingApiClient();
    await expect(send(client, { maxRetries: -1 })).rejects.toThrow(TypeError);
    expect(client.url).toBe("");
  });

  test("per-call headers are sent", async () => {
    const client = new RecordingApiClient();
    await send(client, { headers: { "X-Trace-Id": "abc" } });
    expect(client.headers["X-Trace-Id"]).toBe("abc");
  });

  test("bhv operations 001 a per-call header replaces a default or operation header of the same name, whatever its case", async () => {
    const client = new RecordingApiClient();
    const config = new Configuration({
      baseUrl: "http://localhost",
      defaultHeaders: { "X-Region": "default" },
    });
    await send(
      client,
      { headers: { "x-region": "call", "x-op": "call" } },
      config,
      { "X-Op": "operation" },
    );
    expect(client.headers["x-region"]).toBe("call");
    expect(client.headers["X-Region"]).toBeUndefined();
    expect(client.headers["x-op"]).toBe("call");
    expect(client.headers["X-Op"]).toBeUndefined();
  });

  test("bhv retries 005 per-call headers never replace the authentication headers", async () => {
    const client = new RecordingApiClient();
    const testApi = new TestableApi(
      client,
      new Configuration({ baseUrl: "http://localhost" }),
      new TestAuthenticator({ Authorization: "Bearer real" }),
    );
    await testApi.callForResult(
      "GET",
      "/items",
      {},
      {},
      null,
      ["application/json"],
      "application/json",
      null,
      undefined,
      { headers: { Authorization: "Bearer spoofed" } },
    );
    expect(client.headers["Authorization"]).toBe("Bearer real");
  });

  test("per-call header names are treated as credential headers on a redirect", async () => {
    const client = new RecordingApiClient();
    await send(client, { headers: { "X-Call-Token": "abc" } });
    expect(client.sendOptions?.credentialHeaderNames).toContain("X-Call-Token");
  });

  test("a per-call header with a non-string value is refused", async () => {
    const headers = { "X-Count": 3 } as unknown as Record<string, string>;
    await expect(send(new RecordingApiClient(), { headers })).rejects.toThrow(
      /Invalid per-call header/,
    );
  });
});
